/**
 * Currency conversion for the money reporting, and nothing else.
 *
 * WHY THIS EXISTS. Until EU prices, every subscription billed in USD and the
 * board reported in "whichever currency holds the most money", silently
 * leaving the rest out of MRR. From the EUR launch a large share of customers
 * pay in euros, and a headline that drops them would read as a collapse that
 * never happened. Everything is now converted to USD and summed.
 *
 * THE RATES are monthly ECB averages in fx-rates.ts, generated by
 * `node scripts/fx-rates-refresh.mjs` (run from apps/web) and checked in. No
 * network call happens at render time. A month later than the table uses the
 * latest month, and one earlier uses the first: a stale rate is a few percent
 * of FX noise, while a missing one would be a hole in the revenue.
 *
 * MINOR UNITS ARE ASSUMED TO HAVE TWO DECIMALS, which is true of USD and of
 * every currency in the table. A zero-decimal currency (JPY, KRW) must not be
 * added to the table without handling its exponent here, or it converts a
 * hundred times too small.
 *
 * AN UNKNOWN CURRENCY CONVERTS TO null, never to zero. Callers report it by
 * name (`otherCurrencies`), so a figure that leaves money out says so.
 */

import { USD_PER_UNIT_BY_MONTH } from './fx-rates.ts';

const MONTHS = Object.keys(USD_PER_UNIT_BY_MONTH).sort();

/** `YYYY-MM` in UTC for a Unix-seconds instant. */
export function monthOf(unixSeconds: number): string {
  return new Date(unixSeconds * 1000).toISOString().slice(0, 7);
}

/**
 * USD per one unit of `currency` in `month` (`YYYY-MM`), or null when the
 * table has no rate for that currency.
 */
export function usdPerUnit(currency: string, month: string): number | null {
  const code = currency.toLowerCase();
  if (code === 'usd') return 1;
  if (MONTHS.length === 0) return null;
  const key = month < MONTHS[0] ? MONTHS[0] : month;
  // Newest month at or before `key`: later months use the latest rate, and a
  // gap inside the table falls back to the nearest earlier month.
  for (let i = MONTHS.length - 1; i >= 0; i -= 1) {
    if (MONTHS[i] > key) continue;
    const rate = USD_PER_UNIT_BY_MONTH[MONTHS[i]]?.[code];
    if (rate != null && Number.isFinite(rate) && rate > 0) return rate;
  }
  return null;
}

/**
 * Minor units of `currency` as USD minor units, at the month's average rate.
 * Unrounded: callers sum first and round once, as the MRR math always has.
 * USD passes through untouched, so a USD-only account reads exactly as before.
 */
export function toUsdMinor(amountMinor: number, currency: string, month: string): number | null {
  if (currency.toLowerCase() === 'usd') return amountMinor;
  const rate = usdPerUnit(currency, month);
  return rate == null ? null : amountMinor * rate;
}

/** A Stripe charge reduced to what the cash views read. */
export type ChargeAmounts = {
  amount: number;
  amount_refunded?: number | null;
  currency: string;
  /** Unix seconds. */
  created: number;
};

/**
 * Charges as USD cash rows for `rollUpCash`, each at the rate of the month it
 * landed in, rounded per charge so the month totals stay whole cents.
 *
 * Replaces "take the first charge's currency and add everything up in it",
 * which would have summed euros as dollars the day the first EUR sale landed.
 * Charges in a currency with no rate are left out and named.
 */
export function chargesInUsd(charges: ChargeAmounts[]): {
  rows: { grossMinor: number; refundedMinor: number; at: string }[];
  otherCurrencies: string[];
} {
  const rows: { grossMinor: number; refundedMinor: number; at: string }[] = [];
  const other = new Set<string>();
  for (const charge of charges) {
    const month = monthOf(charge.created);
    const gross = toUsdMinor(charge.amount, charge.currency, month);
    const refunded = toUsdMinor(charge.amount_refunded ?? 0, charge.currency, month);
    if (gross == null || refunded == null) {
      other.add(charge.currency.toLowerCase());
      continue;
    }
    rows.push({
      grossMinor: Math.round(gross),
      refundedMinor: Math.round(refunded),
      at: new Date(charge.created * 1000).toISOString(),
    });
  }
  return { rows, otherCurrencies: [...other].sort() };
}
